JS='''const d=DATA;let current=0,playing=!matchMedia('(prefers-reduced-motion: reduce)').matches,tick=0,visible=true;const cinema=document.querySelector('.cinema');const $=s=>document.querySelector(s);function render(){let x=d.steps[current];cinema.className='cinema scene'+current+(playing?'':' paused');$('#sceneTitle').textContent=x[0];$('#caption').textContent=x[1];$('#status').textContent=x[2];$('#engineLabel').textContent=x[4]||x[3];$('#counter').textContent='0'+(current+1)+' / 05';$('#play').textContent=playing?'Ⅱ Pause':'▶ Play';$('#play').setAttribute('aria-pressed',playing);document.querySelectorAll('.step').forEach((e,i)=>{e.classList.toggle('active',i===current);e.setAttribute('aria-current',i===current?'step':'false')});document.querySelectorAll('.row strong').forEach((e,i)=>{e.textContent=current===0?'Waiting for intake':(current>=3&&d.id==='shortlist'&&i===2?'Four weeks, confirmed':(i===3&&current>=3?d.finalValue:d.rows[i][1]));});}function go(n){current=(n+5)%5;tick=0;render()}$('#play').onclick=()=>{playing=!playing;render()};$('#replay').onclick=()=>{playing=true;go(0)};$('#nextStep').onclick=()=>{playing=false;go(current+1)};document.querySelectorAll('.step').forEach((e,i)=>e.onclick=()=>{playing=false;go(i)});new IntersectionObserver(e=>{visible=e[0].isIntersecting},{threshold:.15}).observe(cinema);setInterval(()=>{if(playing&&visible&&!document.hidden){tick++;if(tick>=7)go(current+1)}},1000);document.querySelector('.exception').addEventListener('toggle',e=>{if(e.target.open){playing=false;render()}});const fmt=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:0}).format(n);function calc(){const v=+$('#volume').value,s=+$('#saved').value;$('#vOut').textContent=fmt(v);$('#sOut').textContent=s+' min';$('#hours').textContent=fmt(v*s/60)+' hours';$('#money').textContent='$'+fmt(v*s/60*d.rate);$('#formula').textContent=fmt(v)+' × '+s+' minutes ÷ 60 × $'+d.rate+'/hour';}$('#volume').oninput=calc;$('#saved').oninput=calc;$('#scopeButton').onclick=()=>$('#scopeModal').showModal();$('#closeModal').onclick=()=>$('#scopeModal').close();render();calc();'''
(R/'demo.js').write_text(JS)
esc=lambda s:html.escape(str(s))
def build(d):
 p=R/d['id'];p.mkdir(exist_ok=True)
 d['finalValue']={'fieldquote':'Approved part confirmed','changeproof':'PM reviewed','loadclear':'Replacement scan approved','exchangeflow':'Received by warehouse','shortlist':'Approved by recruiter'}[d['id']]
 typ=d['input_type'];special={'voice':'<div class="wave">'+('<i></i>'*28)+'</div>','document':'<div class="doc-lines"></div>','ticket':'<div class="doc-lines"></div>','profile':'<div class="avatar">AM</div>','chat':'<div class="product"></div>'}[typ]
 pain=''.join(f'<div class="pain"><span class="num">0{i+1}</span><p>{esc(t)}</p></div>' for i,t in enumerate(d['pains']))
 rows=''.join(f'<div class="row"><span>{esc(a)}</span><strong '+('id="lastValue"' if i==3 else '')+f'>{esc(b)}</strong></div>' for i,(a,b) in enumerate(d['rows']))
 steps=''.join(f'<button class="step" data-step="{i}"><small>0{i+1}</small>{esc(s[3])}</button>' for i,s in enumerate(d['steps']))
 scope=''.join(f'<li>{esc(t)}</li>' for t in d['scope'])
 source2=f'<p><a href="{d["source2"]}">Loop × Gorgias native integration overview ↗</a></p>' if 'source2'in d else ''
 page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{d['name']} — implementation proposal</title><link rel="stylesheet" href="../style.css"></head><body style="--accent:{d['color']};--tint:{d['light']}"><header><a class="brand" href="../index.html">{d['name']}<span>●</span></a><nav><a href="#demo">Walkthrough</a><a href="#scope">The system</a><a href="#value">The value</a><a href="#next">Next step ↗</a></nav></header><main><section class="hero"><div><div class="eyebrow">{d['tag']} / IMPLEMENTATION PROPOSAL</div><h1>{d['headline']}</h1></div><div><p class="intro">{esc(d['sub'])}</p><a class="watchlink" href="#demo">Watch one job move through it ↓</a><div class="hero-rule"><span>YOUR EXISTING TOOLS</span><span>HUMAN APPROVAL</span><span>ONE CLEAR WORKFLOW</span></div></div></section>
<section class="demo-wrap" id="demo"><div class="cinema"><div class="demo-head"><div><div class="eyebrow">THE WORKFLOW · IN MOTION</div><h2 class="scene-title" id="sceneTitle"></h2><p class="caption" id="caption"></p></div><span class="badge">Illustrative demo<br>Synthetic data · no live connections</span></div><div class="stage"><div class="device input"><div class="device-head">{d['input_title']}<span>●</span></div><div class="device-body"><div class="meta">{esc(d['input_meta'])}</div>{special}<div class="bubble">{esc(d['input_text'])}</div><span class="meta">Source record retained with the task</span></div></div><div class="engine"><div class="orb">✦</div><div class="engine-label" id="engineLabel"></div><div class="connector"></div><div class="engine-note">Read the source.<br>Check the rules.<br>Ask when uncertain.</div></div><div class="device output"><div class="device-head">{d['output_title']}<span>REVIEW QUEUE</span></div><div class="device-body"><h3>{d['output_name']}</h3>{rows}<div class="status" id="status"></div></div></div></div><div class="controls"><button class="primary" id="play">Ⅱ Pause</button><button id="replay">↻ Replay</button><button id="nextStep">Next step →</button><span class="counter" id="counter"></span></div><div class="timeline">{steps}</div><details class="exception"><summary>What if something goes wrong?</summary><p>{esc(d['exception'])}</p></details></div></section>
<section class="section" id="problem"><div class="eyebrow">01 / THE PROBLEM</div><h2>{d['problem']}</h2><div class="three">{pain}</div></section>
<section class="section" id="scope"><div class="eyebrow">02 / WHAT YOU GET</div><h2>One connected process.<br><em>A clear person in control.</em></h2><div class="split"><div><p class="statement" style="font-size:26px">{esc(d['offer'])}</p><p>{esc(d['system'])}</p><p class="review"><strong>Outside this scope:</strong> {esc(d['exclude'])}</p></div><div class="panel"><h3>The implementation</h3><ul class="list">{scope}</ul><p class="review"><strong>We’ll need:</strong> {esc(d['dependency'])}</p></div></div></section>
<section class="section dark" id="value"><div class="inner"><div class="eyebrow">03 / MAKE THE NUMBERS YOURS</div><h2>What is the work<br>taking from your team?</h2><div class="split"><div class="panel calc"><span class="badge">Illustrative monthly scenario · USD</span><label for="volume">{d['metric']}<output id="vOut"></output></label><input id="volume" type="range" min="0" max="{d['volume']*3}" step="10" value="{d['volume']}"><label for="saved">Minutes saved per {d['unit'][:-1] if d['unit']!='entries' else 'entry'}<output id="sOut"></output></label><input id="saved" type="range" min="0" max="{d['before']}" value="{d['before']-d['after']}"><p class="value-note">Starting assumption: {d['before']} minutes today → {d['after']} minutes including human review. Loaded staff cost: ${d['rate']}/hour. Replace with your measured baseline.</p></div><div><div class="big" id="hours"></div><p>of team capacity released per month</p><div class="line"></div><div style="font:34px Georgia,serif" id="money"></div><p class="value-note">Monthly capacity value, not cash saved or new revenue.</p><p class="value-note" id="formula"></p><p class="value-note">{esc(d['extra'])} Implementation, software and support costs must be deducted before assessing net value.</p></div></div></div></section>
<section class="section" id="launch"><div class="eyebrow">04 / FROM EXAMPLE TO YOUR BUSINESS</div><h2>Prove the workflow.<br><em>Then put it to work.</em></h2><div class="stages"><div class="milestone"><span class="num">01</span><h3>Map a real example</h3><p>Trace recent work, measure the baseline and check existing software.</p></div><div class="milestone"><span class="num">02</span><h3>Connect a sandbox</h3><p>Confirm access and build one bounded flow using approved sample records.</p></div><div class="milestone"><span class="num">03</span><h3>Test the hard cases</h3><p>Missing details, duplicates and incorrect matches must stop safely.</p></div><div class="milestone"><span class="num">04</span><h3>Launch with an owner</h3><p>Train your approver, agree support and monitor the first controlled batch.</p></div></div><div class="split" style="margin-top:35px"><div><h3>What passing looks like</h3><p>{esc(d['accept'])}</p></div><div><h3>Use what already works</h3><p>{esc(d['alternative'])}</p></div></div></section>
<section class="cta" id="next"><div class="inner"><div class="eyebrow">05 / THE NEXT STEP</div><h2 class="statement">Let’s run your last real example<br>through this process.</h2><p style="max-width:700px">{esc(d['question'])}</p><button class="button" id="scopeButton">See what to bring to the scope call ↗</button><p class="review">Scope, delivery date, ownership, support and commercial terms are agreed after the technical review.</p><details class="notes"><summary>Research behind this proposal</summary><p>{esc(d['evidence'])}</p><p><a href="{d['source']}" target="_blank" rel="noopener">{esc(d['source_name'])} ↗</a></p>{source2}<p>Our proposed service and this demonstration are hypotheses, not that provider’s product or results. <a href="../research.html#{d['id']}">Open Blake’s research notes →</a></p></details></div></section></main><footer><a href="../index.html">← All five proposals</a><span>Private concept proposal · 25 October 2026</span></footer><dialog class="modal" id="scopeModal"><button class="close" id="closeModal" aria-label="Close">×</button><div class="eyebrow">SCOPE CALL PREPARATION</div><h2>Bring the work.<br>We’ll map the change.</h2><ul class="list"><li>Three recent, redacted examples of the workflow.</li><li>The people, software and approval steps involved.</li><li>Your monthly volume and actual handling time.</li><li>The result that would make this worthwhile.</li></ul><p>{esc(d['fit'])}</p><p class="review">This preview does not book a meeting or send information.</p></dialog><script>const DATA={json.dumps(d)};</script><script src="../demo.js"></script></body></html>'''
 (p/'index.html').write_text(page)
for d in D[:1]:build(d)
print('Built benchmark:',R/'fieldquote/index.html')
# Build remaining only when called with --all after benchmark review.
import sys
if '--all' in sys.argv:
 for d in D[1:]:build(d)
 cards=''
 for i,d in enumerate(D):
  cards+=f'''<a class="gallery-card" href="{d['id']}/index.html" style="--accent:{d['color']};--tint:{d['light']}"><div class="card-top"><span>0{i+1} / {d['tag']}</span><span>↗</span></div><div class="card-scene"><div class="mini-in">{d['input_title']}<div class="mini-lines"></div></div><div class="mini-orb">✦</div><div class="mini-out">{d['output_title']}<div class="mini-status">{esc(d['steps'][4][2])}</div></div></div><h2>{d['name']}<span>▶</span></h2><p>{esc(d['sub'])}</p><div class="card-foot">AUTOPLAY WALKTHROUGH <span>OPEN PROPOSAL →</span></div></a>'''
 gallery=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jarvis — Five implementation proposals</title><link rel="stylesheet" href="style.css"><style>body{{background:#101d29;color:#eef1f3}}header{{background:#101d29e8;border-color:#ffffff18}}header a{{color:#c3d1dc}}.gallery-intro{{max-width:1450px;margin:auto;padding:65px 6vw 45px}}.gallery-intro h1{{font-size:clamp(45px,6vw,88px);max-width:900px}}.gallery-intro p{{color:#b0bfcd;max-width:680px}}.gallery{{max-width:1450px;padding:0 6vw 70px;margin:auto;display:grid;grid-template-columns:1fr 1fr;gap:28px}}.gallery-card{{display:block;text-decoration:none;border-radius:18px;background:#f4f1e9;color:#172b3a;overflow:hidden;transition:transform .2s}}.gallery-card:hover{{transform:translateY(-5px)}}.card-top{{display:flex;justify-content:space-between;padding:25px 28px;font-size:10px;letter-spacing:1.5px;color:var(--accent);font-weight:bold}}.card-scene{{margin:0 25px;background:#172c3c;border-radius:10px;padding:32px 20px;display:flex;align-items:center;gap:12px;height:170px}}.mini-in,.mini-out{{background:#f6f8f9;border-radius:7px;padding:15px 10px;font-size:8px;flex:1;min-width:0;height:92px}}.mini-lines{{margin-top:12px;height:40px;background:repeating-linear-gradient(0deg,transparent 0 8px,#d0d7dc 9px 11px)}}.mini-orb{{color:var(--accent);font-size:25px}}.mini-status{{background:var(--tint);color:var(--accent);padding:9px 5px;margin-top:12px;font-size:9px;line-height:1.4}}.gallery-card h2{{font:38px Georgia,serif;display:flex;justify-content:space-between;margin:26px 28px 10px}}.gallery-card h2 span{{font:14px Arial;color:var(--accent);padding:13px;border:1px solid var(--accent);border-radius:50%}}.gallery-card p{{margin:0 28px 25px;font-size:14px;min-height:72px}}.card-foot{{border-top:1px solid #dedbd3;padding:20px 28px;display:flex;justify-content:space-between;gap:12px;font-size:9px;font-weight:bold;letter-spacing:1px}}.research-link{{display:inline-block;color:#d8c49d;margin-top:12px}}footer{{color:#9badbc}}@media(max-width:800px){{.gallery{{grid-template-columns:1fr}}.card-foot{{font-size:8px}}}}</style></head><body><header><a class="brand" href="index.html">JARVIS <span style="font-size:12px;letter-spacing:2px;color:#91a8bb">/ OFFER LAB</span></a><a href="research.html" style="font-size:12px">Research & comparisons ↗</a></header><main><div class="gallery-intro"><div class="eyebrow" style="color:#d8c49d">FIVE SERVICES / FIVE WORKING PRESENTATIONS</div><h1>See the problem.<br>Watch the <em style="color:#d8c49d">change.</em></h1><p>Five researched service concepts, each with its own proposal and animated workflow. Open one, watch the job move through it, then inspect the scope and numbers.</p><a class="research-link" href="research.html">Start with the plain-English comparison →</a></div><div class="gallery">{cards}</div></main><footer><span>Private review pack · fictional brands · simulated workflows</span><span>25 OCT 2026</span></footer></body></html>'''
 (R/'index.html').write_text(gallery)
 research=''
 for d in D:
  hours=d['volume']*(d['before']-d['after'])/60
  research+=f'''<section class="section" id="{d['id']}"><div class="eyebrow">{d['tag']}</div><h2>{d['name']}: what we would actually sell</h2><p class="statement" style="font-size:26px">{esc(d['offer'])}</p><div class="split"><div><h3>Buyer and pain</h3><p>{esc(d['buyer'])} Decision-maker: {esc(d['owner'])}.</p><h3>System and delivery</h3><p>{esc(d['system'])}</p><p>{esc(d['route'])}</p><p><strong>Difficulty:</strong> {esc(d['complexity'])}</p><h3>How we would acquire clients</h3><p>{esc(d['acquire'])}</p></div><div><h3>What the evidence establishes</h3><p>{esc(d['evidence'])}</p><p><a href="{d['source']}">{esc(d['source_name'])} ↗</a></p><p><strong>Evidence level:</strong> {esc(d['strength'])}. Relevant page sections opened and inspected on 25 October 2026; no customer interviews conducted.</p><h3>The strongest objection</h3><p>{esc(d['alternative'])}</p></div></div><div class="panel"><h3>Value model, not a prediction</h3><p>Illustrative monthly inputs: {d['volume']:,} {d['unit']} × ({d['before']} − {d['after']}) minutes ÷ 60 × ${d['rate']}/hour = <strong>${hours*d['rate']:,.0f} of capacity value</strong> ({hours:,.1f} hours). All inputs are assumptions; human review remains in the after-time. {esc(d['extra'])}</p><p>No proposed fee or net ROI is justified yet. Obtain a technical estimate (build, QA, project management, support), exact connector/API licences and usage costs, then compare conservative annual benefit against total first-year cost. The capacity model alone may not support a high-ticket fee at low volume.</p><p><strong>Guarantee design:</strong> {esc(d['deal'])} If work-free support is chosen later, define the measured outcome, start, waived service fee, continuing work, client obligations and third-party costs consistently. No invented outcome guarantee is approved in this pack.</p></div><h3>What we need before selling</h3><p>{esc(d['question'])} {esc(d['dependency'])}</p><p><strong>Acceptance:</strong> {esc(d['accept'])}</p><p><strong>Market size:</strong> not counted in this bounded pass. Build a named list of eligible businesses after stack and volume criteria are confirmed; do not multiply total industry revenue into a fake TAM. <strong>Price / willingness to buy:</strong> untested. <strong>Integration:</strong> proposed, not connected. <strong>Current urgency:</strong> not established by an older case study.</p><a class="button" href="{d['id']}/index.html">Open the proposal ↗</a></section>'''
 (R/'research.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Five proposals — research and commercial review</title><link rel="stylesheet" href="style.css"></head><body style="--accent:#a16135;--tint:#f2e8dc"><header><a class="brand" href="index.html">JARVIS / RESEARCH</a><a href="index.html">← Proposals</a></header><div class="section"><div class="eyebrow">BLAKE’S INTERNAL REVIEW · NOT BUYER COPY</div><h1>Five possibilities.<br>Different levels of conviction.</h1><p class="intro">My first two to investigate are HVAC repair quoting and construction extra-work capture: the commercial event is easy to understand. Freight billing has a clear operational case. Ecommerce is a more advanced integration. Recruitment is easy to explain but has the weakest custom-build differentiation.</p><p>These are source-supported workflow opportunities, not five proven high-ticket offers. Each has an existing software alternative. The commercial job is to find a buyer with a genuine gap, not attach an AI label to a feature they already own.</p><p>The demos use fictional records and show proposed behaviour. They do not call APIs, store customer data or perform business actions. No prices, testimonials, market counts or conversion claims were invented.</p><nav style="flex-wrap:wrap">{''.join(f'<a href="#{d["id"]}">{d["name"]}</a>' for d in D)}</nav></div>{research}<footer><a href="index.html">← All proposals</a><span>Research reviewed 25 October 2026</span></footer></body></html>''')
 (R/'source'/'offers.json').write_text(json.dumps(D,indent=2))
 (R/'README.txt').write_text('Open index.html in Chrome or Safari. No install or server required. Each proposal has a 35-second looping illustrative demo, pause/replay/step controls, an exception state, calculator and scope-call checklist. Reduced-motion preference disables automatic playback. Research and assumptions are in research.html and source/offers.json. Nothing is connected to live systems. All brands and demo records are fictional. Keep the folder together when sharing.\n')
 print('All five + gallery + research built')
